use verus::prelude::*;

/// Returns the sign of the given 32-bit integer:
///  -  1 if `x` is strictly positive
///  -  0 if `x` is zero
///  - -1 if `x` is strictly negative
#[ensures(
    // exactly one of these three cases holds
    (x > 0  && result ==  1) ||
    (x == 0 && result ==  0) ||
    (x < 0  && result == -1)
)]
fn sign_of(x: i32) -> i32 {
    if x > 0 {
        1
    } else if x < 0 {
        -1
    } else {
        0
    }
}

/// Transforms the input vector into a vector of the same length
/// where each element is replaced by its sign.
#[ensures(result.len() == a.len())]
#[ensures(forall(|i: usize| i < a.len() ==> result[i] == sign_of(a[i])))]
fn sign(a: Vec<i32>) -> Vec<i32> {
    a.into_iter().map(sign_of).collect()
}

